CREATE TABLE "debts" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "debts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" text NOT NULL,
	"name" text NOT NULL,
	"kind" text NOT NULL,
	"amount" bigint DEFAULT 0 NOT NULL,
	"credit_limit" bigint,
	"installment" bigint,
	"cycle" text DEFAULT 'monthly' NOT NULL,
	"due_day" integer,
	"due_month" integer,
	"note" text,
	"sort_order" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "debts_amount_nonnegative" CHECK ("debts"."amount" >= 0),
	CONSTRAINT "debts_limit_positive" CHECK ("debts"."credit_limit" is null or "debts"."credit_limit" > 0),
	CONSTRAINT "debts_installment_positive" CHECK ("debts"."installment" is null or "debts"."installment" > 0),
	CONSTRAINT "debts_due_day_range" CHECK ("debts"."due_day" is null or "debts"."due_day" between 1 and 31),
	CONSTRAINT "debts_due_month_range" CHECK ("debts"."due_month" is null or "debts"."due_month" between 1 and 12)
);
